//! Spatial math vs the independent E4 `NumPy` oracle (`tests/oracle/spatial_oracle.py`):
//! `SE(3)` composition, quaternion rotation of points/directions/vectors, SLERP,
//! and the geodetic chain. `cargo test -p drm-spatial math`.
//!
//! REQ: REQ-SPATIAL-036, REQ-SPATIAL-038, REQ-SPATIAL-012.

use drm_spatial::{
    Direction3, Lla, Point3, Transform3, UnitQuat, Vector3, compose, geodetic_to_enu,
    transform_direction, transform_point, transform_vector, wgs84_to_ecef,
};
use serde_json::Value;

/// Oracle fixture generated by `tests/oracle/spatial_oracle.py`.
/// REQ: REQ-SPATIAL-036.
fn oracle() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/fixtures/spatial/oracle_vectors.json"
    );
    let text = std::fs::read_to_string(path).unwrap_or_else(|e| unreachable!("oracle: {e}"));
    serde_json::from_str(&text).unwrap_or_else(|e| unreachable!("parse oracle: {e}"))
}

/// Reads a fixed-length `f64` array from a JSON value.
/// REQ: REQ-SPATIAL-036.
fn arr3(v: &Value) -> [f64; 3] {
    let a = v.as_array().unwrap_or_else(|| unreachable!("array"));
    [
        a[0].as_f64().unwrap_or_default(),
        a[1].as_f64().unwrap_or_default(),
        a[2].as_f64().unwrap_or_default(),
    ]
}

/// Reads a 4-element `f64` array from a JSON value.
/// REQ: REQ-SPATIAL-036.
fn arr4(v: &Value) -> [f64; 4] {
    let a = v.as_array().unwrap_or_else(|| unreachable!("array"));
    [
        a[0].as_f64().unwrap_or_default(),
        a[1].as_f64().unwrap_or_default(),
        a[2].as_f64().unwrap_or_default(),
        a[3].as_f64().unwrap_or_default(),
    ]
}

/// Asserts two `[f64; 3]` arrays agree within `tol`.
/// REQ: REQ-SPATIAL-036.
fn close3(got: [f64; 3], want: [f64; 3], ctx: &str) {
    for i in 0..3 {
        assert!(
            (got[i] - want[i]).abs() < 1e-9,
            "{ctx}[{i}]: got {got:?} want {want:?}"
        );
    }
}

/// Asserts two `[f64; 4]` arrays agree within `tol`.
/// REQ: REQ-SPATIAL-036.
fn close4(got: [f64; 4], want: [f64; 4], ctx: &str) {
    // Quaternions are sign-ambiguous (`q` and `-q` are the same rotation).
    let direct = (0..4).all(|i| (got[i] - want[i]).abs() < 1e-9);
    let negated = (0..4).all(|i| (got[i] + want[i]).abs() < 1e-9);
    assert!(direct || negated, "{ctx}: got {got:?} want {want:?}");
}

/// REQ: REQ-SPATIAL-036 — every oracle vector's point/direction/vector
/// transform and composition match `drm-spatial`.
#[test]
#[allow(clippy::many_single_char_names)] // `a`, `b`, `p`, `d`, `v` are the oracle's names
fn math_transform_oracle() {
    let doc = oracle();
    let vectors = doc["vectors"]
        .as_array()
        .unwrap_or_else(|| unreachable!("vectors"));
    assert!(vectors.len() >= 20);
    for (n, case) in vectors.iter().enumerate() {
        let a = Transform3::new(arr3(&case["a"]["t"]), arr4(&case["a"]["q"]))
            .unwrap_or_else(|e| unreachable!("a: {e}"));
        let b = Transform3::new(arr3(&case["b"]["t"]), arr4(&case["b"]["q"]))
            .unwrap_or_else(|e| unreachable!("b: {e}"));
        let p = Point3::new(
            case["p"][0].as_f64().unwrap_or_default(),
            case["p"][1].as_f64().unwrap_or_default(),
            case["p"][2].as_f64().unwrap_or_default(),
        )
        .unwrap_or_default();
        let d = Direction3::try_new(
            case["d"][0].as_f64().unwrap_or_default(),
            case["d"][1].as_f64().unwrap_or_default(),
            case["d"][2].as_f64().unwrap_or_default(),
        )
        .unwrap_or_else(|e| unreachable!("d: {e}"));
        let v = Vector3::new(
            case["v"][0].as_f64().unwrap_or_default(),
            case["v"][1].as_f64().unwrap_or_default(),
            case["v"][2].as_f64().unwrap_or_default(),
        )
        .unwrap_or_default();

        let tp = transform_point(&a, p);
        close3(tp.components(), arr3(&case["transform_a_point"]), "point");
        let td = transform_direction(&a, d);
        close3(
            td.components(),
            arr3(&case["transform_a_direction"]),
            "direction",
        );
        let tv = transform_vector(&a, v);
        close3(tv.components(), arr3(&case["transform_a_vector"]), "vector");

        let ab = compose(&a, &b);
        close3(ab.translation, arr3(&case["compose_ab"]["t"]), "compose.t");
        close4(ab.rotation, arr4(&case["compose_ab"]["q"]), "compose.q");

        let slerp = a.quat().slerp(b.quat(), 0.5);
        close4(
            slerp.into_components(),
            arr4(&case["slerp_a_b_half"]),
            "slerp",
        );
        let _ = n;
    }
}

/// REQ: REQ-SPATIAL-012 — the WGS84/ECEF/ENU chain matches the oracle.
#[test]
fn math_geodetic_oracle() {
    let doc = oracle();
    let cases = doc["geodetic"]
        .as_array()
        .unwrap_or_else(|| unreachable!("geodetic"));
    assert!(!cases.is_empty());
    for case in cases {
        let lla = Lla {
            lat_rad: case["lla"][0].as_f64().unwrap_or_default(),
            lon_rad: case["lla"][1].as_f64().unwrap_or_default(),
            alt_m: case["lla"][2].as_f64().unwrap_or_default(),
        };
        let anchor = Lla {
            lat_rad: case["anchor"][0].as_f64().unwrap_or_default(),
            lon_rad: case["anchor"][1].as_f64().unwrap_or_default(),
            alt_m: case["anchor"][2].as_f64().unwrap_or_default(),
        };
        let ecef = wgs84_to_ecef(lla);
        close3([ecef.x, ecef.y, ecef.z], arr3(&case["ecef"]), "ecef");
        let enu = geodetic_to_enu(lla, anchor);
        close3([enu.east, enu.north, enu.up], arr3(&case["enu"]), "enu");
    }
}

/// REQ: REQ-SPATIAL-036 — identity quaternion normalization is idempotent.
#[test]
fn math_identity_is_unit() {
    assert!((UnitQuat::IDENTITY.norm() - 1.0).abs() < 1e-15);
}
